pm.test("Prestamo registrado en estado activo", function () {
    const json = pm.response.json();
    pm.expect(json.success).to.be.true;
    pm.expect(json.data.estado).to.eql("activo");
});

pm.test("Status code es 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Prestamo devuelto con fecha real", function () {
    const json = pm.response.json();
    pm.expect(json.success).to.be.true;
    pm.expect(json.data.estado).to.eql("devuelto");
    pm.expect(json.data.fecha_devolucion_real).to.not.be.null;
});

pm.test("Status code es 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Token generado y almacenado correctamente", function () {
    const response = pm.response.json();
    
    pm.expect(response.success).to.be.true;
    pm.expect(response.data).to.have.property("token");
    pm.expect(response.data.token).to.be.a("string");

    pm.collectionVariables.set("token", response.data.token);
    console.log("Token guardado en la colección:", response.data.token);
});

pm.test("Status code es 401 Unauthorized", function () {
    pm.response.to.have.status(401);
});

pm.test("Mensaje de credenciales inválidas", function () {
    const json = pm.response.json();
    pm.expect(json.success).to.be.false;
});
